const express = require('express');
const app = express();
const port = process.env.PORT || 8080;

app.use(express.json());

/**
 * FIXED IMPLEMENTATION (Resolution generated by cf-log-trace-agent):
 * 
 * 1. Added defensive check for transactionCount === 0 to avoid division by zero.
 * 2. Wrapped startup initialization inside safe try/catch block with fallback value.
 */
function calculateTransactionRatio(totalSum, transactionCount) {
    // RESOLUTION: Defensive check prevents division by zero error
    if (!transactionCount || transactionCount === 0) {
        console.warn('[METRICS] Zero transactions detected. Defaulting ratio to 0.');
        return 0;
    }
    return totalSum / transactionCount;
}

function initializeAppMetrics() {
    console.log('[STARTUP] Initializing metrics engine and database warm-up...');
    const sampleSum = 5000;
    const initialBatchCount = 0;

    try {
        // Safe execution with error boundary
        const initialRatio = calculateTransactionRatio(sampleSum, initialBatchCount);
        console.log(`[STARTUP] Initial ratio computed safely: ${initialRatio}`);
    } catch (err) {
        console.warn(`[STARTUP] Calculation warning handled: ${err.message}. Defaulting to 0.`);
    }
}

app.get('/health', (req, res) => {
    res.status(200).json({ status: 'UP' });
});

app.get('/calculate', (req, res) => {
    const sum = Number(req.query.sum || 100);
    const count = Number(req.query.count || 0);
    const result = calculateTransactionRatio(sum, count);
    res.json({ sum, count, result });
});

initializeAppMetrics();
app.listen(port, () => {
    console.log(`Fixed app listening on port ${port}`);
});
